@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + maxCapacity : int
}

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer extends Person {
  + diploma : string
}

class Member extends Person {}

class Prospect extends Person {}

class Intern extends Trainer {}

class Session {
  + date : date
  + startingHour : time
}

class IndividualSession extends Session {}

class GroupSession extends Session {
  + type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

GroupSession "*" -- "1" Trainer
Trainer "1" -- "*" GroupSession

Session "*" -- "*" Person : participates
Trainer "1" -- "*" Session : supervises

@enduml

